/**
 * ORC Runcrew track poster "Schwelle im Wechsel", transcribed from supplied
 * athlete image (not generated by geolocation, Garmin or artificial pacing).
 * One poster, five groups. Future posters require a new reviewed transcription.
 * Garmin workout specification is read-only until separate server-side approval.
 */
export type OrcGroup='Fuchs'|'Wolf'|'Tiger'|'Bären'|'Capybara'
export type OrcPace={seconds:number;label:string}
export type OrcWorkoutStep={
 kind:'warmup'|'drill'|'interval'|'recovery'|'cooldown'
 distanceMeters?:number;pace?:OrcPace;
 pauseAfterBlock?:boolean;notes?:string
}
export type OrcWorkout={
 posterId:string;group:OrcGroup;name:string;blocks:number[];
 steps:OrcWorkoutStep[];intervalCount:number;
 effortMeters:number;recoveryMeters:number;minimumMeters:number
}
const groups:Record<OrcGroup,{blocks:number[];paces:[number,number,number]}> = {
 Fuchs:{blocks:[3,3,3],paces:[240,230,250]},
 Wolf:{blocks:[3,3,2],paces:[260,250,270]},
 Tiger:{blocks:[3,3,2],paces:[280,270,290]},
 Bären:{blocks:[3,3,1],paces:[300,290,310]},
 Capybara:{blocks:[3,3,1],paces:[320,310,330]}
}
export const ORC_GROUPS=Object.keys(groups) as OrcGroup[]
export const ORC_POSTER_ID='orc-track-schwelle-im-wechsel-poster-01'
export const ORC_POSTER_TITLE='Schwelle im Wechsel'
export function paceLabel(seconds:number):string{
 if(!Number.isInteger(seconds)||seconds<60||seconds>900)throw Error('Ungültiges Lauftempo')
 return String(Math.floor(seconds/60))+':'+String(seconds%60).padStart(2,'0')
}
export function buildOrcWorkout(group:OrcGroup):OrcWorkout{
 const definition=groups[group]
 if(!definition)throw Error('Unbekannte ORC-Gruppe')
 const total=definition.blocks.reduce((a,b)=>a+b,0)
 const steps:OrcWorkoutStep[]=[
  {kind:'warmup',distanceMeters:2000,notes:'Einlaufen – 2 km'},
  {kind:'drill',notes:'Miniband-Übungen; LAP drücken, wenn bereit'}
 ]
 let n=0
 for(let block=0;block<definition.blocks.length;block++){
  for(let i=0;i<definition.blocks[block];i++){
   const seconds=definition.paces[i]
   n++
   steps.push({kind:'interval',distanceMeters:1000,
    pace:{seconds,label:paceLabel(seconds)}})
   if(n<total){
    steps.push({kind:'recovery',distanceMeters:200,
      pauseAfterBlock:i===definition.blocks[block]-1,
      notes:i===definition.blocks[block]-1?
       'Serienpause: 200 m locker traben und trinken':
       '200 m locker traben'})
   }
  }
 }
 steps.push({kind:'cooldown',notes:'Locker auslaufen, danach dehnen; keine Dauer vorgegeben'})
 return {
  posterId:ORC_POSTER_ID,group,name:'ORC · Schwelle im Wechsel · '+group,
  blocks:[...definition.blocks],steps,intervalCount:total,
  effortMeters:total*1000,recoveryMeters:(total-1)*200,
  minimumMeters:2000+total*1000+(total-1)*200
 }
}
/** Workout-spec format for a future private Garmin workoutFromSpec handler.
 * Pace ±5 seconds/km is an explicitly chosen device-alert tolerance,
 * not a claim the poster supplied a target range.
 */
export function toGarminRunningSpec(workout:OrcWorkout){
 return {name:workout.name,sport:'running' as const,
  steps:workout.steps.map(step=>{
   if(step.kind==='warmup')return {type:'warmup',distance:step.distanceMeters}
   if(step.kind==='drill')return {type:'other',lapButton:true,notes:step.notes}
   if(step.kind==='cooldown')return {type:'cooldown',lapButton:true,notes:step.notes}
   if(step.kind==='recovery')return {
    type:'recovery',distance:step.distanceMeters,notes:step.notes}
   const s=step.pace!.seconds
   return {type:'interval',distance:1000,target:{
    pace:{minPerKm:[(s-5)/60,(s+5)/60] as [number,number]}
   }}
  })
 }
}
/** Human-readable private plan description. Not a Garmin remote workout ID. */
export function orcDraftNotes(workout:OrcWorkout):string{
 const paces=workout.steps.filter(s=>s.kind==='interval')
  .map(s=>s.pace?.label).join('/')
 return 'ORC '+ORC_POSTER_TITLE+' · '+workout.group+' ('+
  workout.blocks.join('+')+' × 1000m): 2 km Einlaufen, Minibänder; 1000m @ '+
  paces+' min/km; jeweils 200m Trab zwischen den Intervallen, nach Satz 1/2 Wasser; '+
  'anschließend locker auslaufen + dehnen. Dies ist ein GARMIN_AI-Entwurf, '+
  'noch KEIN Garmin-Workout.'
}
